INSERT INTO public.job_standard_item (id, profile_id, job_code, category, skill_key, skill_name, importance, expected_level, standard_summary, detailed_requirement, scoring_points, risk_signals, status, create_time, update_time) VALUES (7, 1, 'java_backend', 'middleware', 'redis', 'Redis', 'high', 'L2', '理解缓存场景、过期策略和常见问题，如缓存穿透、击穿、雪崩。', '能说明项目里为什么要加缓存、缓存粒度、失效策略和一致性方案。', '是否能解释缓存命中率、热点数据、双写一致性。', '只说“用了 Redis 提高性能”，没有具体策略。', 1, '2026-04-13 21:59:11.432722', '2026-04-13 21:59:11.432722');
