INSERT INTO public.job_standard_vector_store (id, content, metadata, embedding) VALUES ('214d4e0f-c5e9-4031-a047-54371f460997', '岗位：Java后端开发工程师
技能项：Java基础
分类：backend_core
重要级别：high
期望等级：L2
标准描述：掌握 Java 面向对象、集合、异常、泛型、常用 API。
