INSERT INTO public.job_standard_vector_store (id, content, metadata, embedding) VALUES ('b24f3e5b-dbe9-4524-8e0d-bac1826daad5', '岗位：Java后端开发工程师
技能项：Spring / Spring Boot
分类：framework
重要级别：high
期望等级：L2
标准描述：能独立完成基于 Spring Boot 的接口开发、配置管理、异常处理和模块拆分。
