INSERT INTO public.job_standard_vector_store (id, content, metadata, embedding) VALUES ('4b196165-4bda-4bbb-ad95-39a29edd4a53', '岗位：Java后端开发工程师
技能项：MyBatis / ORM
分类：framework
重要级别：medium
期望等级：L2
标准描述：能够进行基础表映射、动态 SQL 编写和分页查询。
