INSERT INTO public.job_standard_vector_store (id, content, metadata, embedding) VALUES ('6f22ea7f-b93a-44b8-81b0-d87799057a6e', '岗位：Java后端开发工程师
技能项：消息队列
分类：middleware
重要级别：medium
期望等级：L1
标准描述：了解异步削峰、解耦、重试和幂等基础。
