INSERT INTO public.job_standard_vector_store (id, content, metadata, embedding) VALUES ('91272fd9-7537-493e-899f-84df7634d86f', '岗位：Java后端开发工程师
技能项：项目真实性
分类：project
重要级别：high
期望等级：L2
标准描述：项目经历必须能说清背景、职责、难点、取舍、结果。
