INSERT INTO public.job_standard_vector_store (id, content, metadata, embedding) VALUES ('1db72b98-a2c5-4b50-9faf-50f8c8af75a1', '岗位：Java后端开发工程师
技能项：AI Agent / RAG 工程加分项
分类：ai_engineering
重要级别：low
期望等级：L1
标准描述：如果候选人做过 AI Agent、RAG、向量检索项目，可作为加分项。
